#!/usr/bin/env bash
# One-click installer (Linux): downloads the latest VR Auto Launcher from GitHub and installs it.
#   curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/vr-autolauncher/main/get.sh | bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
set -euo pipefail
REPO="lokinyauv-create/vr-autolauncher"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
echo "Downloading VR Auto Launcher… / Завантажую VR Auto Launcher…"
curl -fsSL "https://codeload.github.com/$REPO/tar.gz/refs/heads/main" | tar -xz -C "$T" --strip-components=1
bash "$T/linux/install.sh" "$@"
